import { ComponentType, useEffect, useMemo, useState } from "react";
import styles from "./upcoming-block.module.less";

import { createDate, EventAggregator, multipleClassNames } from "@/core/helpers";
import { ScheduleStore } from "@/core/stores";
import { PrimaryButtonLink, SecondaryButtonLink } from "@/core/components/primitives/parks-button/parks-button";
import Carousel from "@/core/components/primitives/carousel/carousel";
import { Tag } from "@/core/types";
import { useTranslation } from "react-i18next";
import { ShowProps } from "@/core/components/primitives/calendar/types/calendar-types";
import { LoadingBlock } from "@/core/components/primitives/loading-block/loading-block";
import { useWindowWidthBreakpoints } from "@/core/hooks/use-window-width-breakpoints";
import { ShowListItem } from "./show-list-item";

export type ListItemProps = Partial<ShowProps> & {
  largeCardMobile?: boolean;
  isTodayCard?: boolean;
};

export type UpcomingBlockProps = {
  today?: boolean;
  tag?: Tag;
  selectedDate?: Date;
  headline?: string;
  subheading?: string;
  upcomingItemLimit?: number;
  showDuplicateEvents?: boolean;
  primaryButtonText?: string;
  primaryButtonLink?: { internalLink?: { slug: string }; externalUrl?: string };
  secondaryButtonText?: string;
  secondaryButtonLink?: { internalLink?: { slug: string }; externalUrl?: string };
  componentTheme?: string;
  /**
   * This is currently mainly used to add a border pattern to the block.
   */
  extraClasses?: string;
  /**
   * @deprecated
   * `listItemRenderer` should no longer be passed, but is only here for backwards compatibility.
   * `ShowListItem` is the default renderer.
   */
  listItemRenderer?: ComponentType<ListItemProps>;
  /**
   * If provided, the show with this id will be excluded from the list of upcoming shows.
   * This is mainly used on the show page to exclude the current show from the list of upcoming shows.
   */
  showContentfulIdToExclude?: string;
  contentfulId: string;
};

export function UpcomingBlock({
  today,
  tag,
  headline,
  subheading,
  upcomingItemLimit = 5,
  primaryButtonText,
  primaryButtonLink,
  secondaryButtonText,
  secondaryButtonLink,
  componentTheme,
  extraClasses,
  listItemRenderer = ShowListItem,
  showContentfulIdToExclude,
  contentfulId,
  ...props
}: UpcomingBlockProps) {
  const { t } = useTranslation();

  const selectedDate = useMemo(() => props.selectedDate ?? createDate(), [props.selectedDate]);
  const showDuplicateEvents = props.showDuplicateEvents ?? false;

  const displayOneItem = upcomingItemLimit === 1;

  const activeDevice = useWindowWidthBreakpoints();
  const [events, setEvents] = useState<Array<ShowProps> | null>(null);

  const primaryButtonLinkUrl = primaryButtonLink?.internalLink?.slug ?? primaryButtonLink?.externalUrl ?? "";
  const secondaryButtonLinkUrl = secondaryButtonLink?.internalLink?.slug ?? secondaryButtonLink?.externalUrl ?? "";

  useEffect(() => {
    let _mounted = true;
    const fetch = async () => {
      try {
        const response = today
          ? await ScheduleStore.getShowsForDateByTag(selectedDate, tag, !showDuplicateEvents)
          : await ScheduleStore.getShowsFromDateByTag(selectedDate, tag, !showDuplicateEvents);

        if (_mounted) {
          setEvents(response);
        }
      } catch (error) {
        EventAggregator.publish("trackException", {
          exception: error,
          customMessage: `UpcomingBlock componentDidMount ${today ? "getShowsForDateByTag" : "getShowsFromDateByTag"}`,
        });
      }
    };
    fetch();

    return () => {
      _mounted = false;
    };
  }, [selectedDate, showDuplicateEvents, tag, today]);

  // We want to hide the entire block if there are no events today, but we should wait for the events to load before we do that, thus the `?.length === 0`
  if (today && events?.length === 0) {
    return null;
  }

  const renderCards = () => {
    if (events === null) {
      return (
        <>
          <LoadingBlock className={styles.loader} />
          <h3 className={styles.loaderText} data-contentful-label-id="loading">
            {t("loading")}
          </h3>
        </>
      );
    }

    if (events.length === 0) {
      return (
        <div className={styles.noShowsLoaded}>
          <h4>{t("upcomingBlockNoEvents")}</h4>
        </div>
      );
    }

    return today ? (
      <TodayCarousel events={events} showDuplicateEvents={showDuplicateEvents} listItemRenderer={listItemRenderer} />
    ) : (
      <UpcomingCards
        events={events}
        showDuplicateEvents={showDuplicateEvents}
        showContentfulIdToExclude={showContentfulIdToExclude}
        displayOneItem={displayOneItem}
        subheading={subheading}
        activeDevice={activeDevice}
        upcomingItemLimit={upcomingItemLimit}
        listItemRenderer={listItemRenderer}
        renderButtons={renderButtons}
      />
    );
  };

  const renderButtons = () => {
    return (
      <div className={multipleClassNames(styles.buttonWrapper, displayOneItem && styles.singleItem)}>
        {primaryButtonText && primaryButtonLinkUrl && (
          <span
            onClick={() => {
              EventAggregator.publish("trackEvent", {
                category: "CTA Concerts",
                action: primaryButtonText,
                label: primaryButtonLinkUrl,
              });
            }}
          >
            <PrimaryButtonLink label={primaryButtonText} url={primaryButtonLinkUrl} isFullWidth />
          </span>
        )}
        {secondaryButtonText && secondaryButtonLinkUrl && (
          <span
            onClick={() => {
              EventAggregator.publish("trackEvent", {
                category: "CTA Concerts",
                action: secondaryButtonText,
                label: secondaryButtonLinkUrl,
              });
            }}
          >
            <SecondaryButtonLink label={secondaryButtonText} url={secondaryButtonLinkUrl} isFullWidth />
          </span>
        )}
      </div>
    );
  };

  return (
    <section
      className={multipleClassNames(
        "block",
        extraClasses,
        componentTheme && `component-theme component-theme-${componentTheme} ${componentTheme}`,
      )}
      data-contentful-id={contentfulId}
    >
      <div className={styles.wrapper}>
        <div className="block--max-width">
          {headline && (
            <h2 className={multipleClassNames(styles.headline, displayOneItem && styles.hiddenDesktop)}>{headline}</h2>
          )}
          {subheading && (
            <h4 className={multipleClassNames(styles.subheading, displayOneItem && styles.hiddenDesktop)}>
              {subheading}
            </h4>
          )}
          {renderCards()}
          {displayOneItem ? null : renderButtons()}
        </div>
      </div>
    </section>
  );
}

const TodayCarousel = ({
  events,
  showDuplicateEvents,
  listItemRenderer: ShowListItem,
}: {
  events: Array<ShowProps>;
  showDuplicateEvents: boolean;
  listItemRenderer: ComponentType<ListItemProps>;
}) => {
  const transformedCards = events.map((item) => {
    const key = showDuplicateEvents ? `${item.id}: ${item.events.map(({ id }) => id).join(",")}` : item.id;
    return <ShowListItem key={key} largeCardMobile={true} isTodayCard={true} {...item} />;
  });

  return <Carousel>{transformedCards}</Carousel>;
};

const UpcomingCards = ({
  events,
  showDuplicateEvents,
  showContentfulIdToExclude,
  displayOneItem,
  subheading,
  activeDevice,
  upcomingItemLimit,
  listItemRenderer: ShowListItem,
  renderButtons,
}: {
  events: Array<ShowProps>;
  showDuplicateEvents: boolean;
  showContentfulIdToExclude: string | undefined;
  displayOneItem: boolean;
  subheading: string | undefined;
  activeDevice: "DEVICE_MOBILE" | "DEVICE_DESKTOP";
  upcomingItemLimit: number;
  listItemRenderer: ComponentType<ListItemProps>;
  renderButtons: () => JSX.Element;
}) => {
  const { t } = useTranslation();

  const shows = showContentfulIdToExclude
    ? events.filter((show) => show.contentful_id !== showContentfulIdToExclude)
    : events;

  const transformedCards = shows.map((item) => {
    const key = showDuplicateEvents ? `${item.id}: ${item.events.map(({ id }) => id).join(",")}` : item.id;
    return <ShowListItem key={key} largeCardMobile={displayOneItem} {...item} />;
  });

  if (displayOneItem) {
    const singleItem = transformedCards[0] ? transformedCards[0] : null;
    const singleItemTitle = singleItem && singleItem.props ? singleItem.props.title : null;
    const singleItemSubHeading = subheading || t("upcomingBlockNextEvent");
    return (
      <div className={styles.singleItemWrapper}>
        <div className={styles.showListSingleItem}>{singleItem}</div>
        <div className={styles.singleItemTextWrapper}>
          <div className={styles.headlines}>
            {singleItemSubHeading && (
              <h4 className={`${styles.hiddenMobile} ${styles.singleItemHeadline}`}>{singleItemSubHeading}</h4>
            )}
            {singleItemTitle && (
              <h2 className={`${styles.hiddenMobile} ${styles.singleItemHeadline}`}>{singleItemTitle}</h2>
            )}
          </div>
          {renderButtons()}
        </div>
      </div>
    );
  }

  if (activeDevice === "DEVICE_MOBILE") {
    return (
      <ul className={styles.itemList}>
        {transformedCards.slice(0, upcomingItemLimit).map((item) => (
          <li className={styles.showListItem} key={item.key}>
            {item}
          </li>
        ))}
      </ul>
    );
  } else {
    return (
      <Carousel classNameNavDotsWrapper={styles.navDotsWrapper} navDots={true}>
        {transformedCards.slice(0, upcomingItemLimit)}
      </Carousel>
    );
  }
};
